#!/usr/bin/env bash
# Fail when a commit of the given revision range carries agent attribution.
# Usage: check_attribution.sh <rev-range>   (e.g. "$BASE..$HEAD", or "$SHA^!" for one commit)
# A bad range is an error (exit 2), never "nothing to check".
set -euo pipefail

range="${1:?usage: check_attribution.sh <rev-range>}"

message_re='claude-session:|\bgenerated with|\bgenerated by \[?claude|anthropic\.com'
coauthor_re='^[[:space:]]*co-authored-by:'
# A squash merge may list Marc himself as co-author: that one is allowed.
marc_coauthor_re='^[[:space:]]*co-authored-by:[[:space:]]*Marc Jeulin[[:space:]]*<|<(jeulinmarc@gmail\.com|[^<>]*jeulinmarc@users\.noreply\.github\.com)>[[:space:]]*$'
email_re='anthropic\.com'
name_re='^claude'

# First line of stdin matching $1 (case-insensitive); exit 0 when there is none.
first_match() { grep -iE -m1 -e "$1" || [ "$?" -eq 1 ]; }

revs="$(git rev-list "$range")" || { echo "check_attribution: cannot resolve the range '$range'" >&2; exit 2; }

checked=0
bad=0
if [ -n "$revs" ]; then
  while read -r sha; do
    checked=$((checked + 1))
    msg="$(git log -1 --format=%B "$sha")"
    hit="$(first_match "$message_re" <<< "$msg")"
    if [ -z "$hit" ]; then
      hit="$(first_match "$coauthor_re" <<< "$msg" | grep -ivE -m1 -e "$marc_coauthor_re" || [ "$?" -eq 1 ])"
    fi
    if [ -z "$hit" ]; then
      idents="$(git log -1 --format='%an%n%ae%n%cn%n%ce' "$sha")"
      { read -r an; read -r ae; read -r cn; read -r ce; } <<< "$idents"
      for pair in "$an|$ae" "$cn|$ce"; do
        name="${pair%%|*}"
        email="${pair#*|}"
        if grep -qiE -e "$email_re" <<< "$email" || grep -qiE -e "$name_re" <<< "$name"; then
          hit="identity: $name <$email>"
          break
        fi
      done
    fi
    if [ -n "$hit" ]; then
      bad=$((bad + 1))
      echo "agent attribution in $(git log -1 --format='%h %s' "$sha")"
      echo "  matched: $hit"
    fi
  done <<< "$revs"
fi

if [ "$bad" -gt 0 ]; then
  echo "$bad of $checked commit(s) carry agent attribution"
  exit 1
fi
echo "checked $checked commit(s): no agent attribution"
